/**
 * Event names published by the portal widget via postMessage.
 * Keep in sync with `apps/portal/src/utilities/events.ts`.
 */
export const EVENTS = {
  WIDGET_READY: 'WIDGET_READY',
  WIDGET_CLOSE: 'WIDGET_CLOSE',
  PAYMENT_INIT: 'PAYMENT_INIT',
  PAYMENT_SUCCESS: 'PAYMENT_SUCCESS',
  PAYMENT_FAILED: 'PAYMENT_FAILED',
  PAYMENT_EXPIRED: 'PAYMENT_EXPIRED',
  PAYMENT_CONFIRMED: 'PAYMENT_CONFIRMED',
  PAYMENT_SENDING: 'PAYMENT_SENDING',
  PAYMENT_PARTIALLY_PAID: 'PAYMENT_PARTIALLY_PAID',
  PAYMENT_FINISHED: 'PAYMENT_FINISHED',
} as const;

export type WidgetEventName = (typeof EVENTS)[keyof typeof EVENTS];

export type WidgetEventPayload = Record<string, unknown>;

export type WidgetEvent = {
  name: WidgetEventName | string;
  payload: WidgetEventPayload;
};

/** Envelope posted from the portal iframe to the host page. */
export type WidgetMessage = {
  source: 'jovepay-widget';
  event: WidgetEvent;
};

export function isWidgetMessage(data: unknown): data is WidgetMessage {
  if (data === null || typeof data !== 'object') {
    return false;
  }
  const record = data as Record<string, unknown>;
  if (record['source'] !== 'jovepay-widget') {
    return false;
  }
  const event = record['event'];
  if (event === null || typeof event !== 'object') {
    return false;
  }
  const eventRecord = event as Record<string, unknown>;
  return typeof eventRecord['name'] === 'string';
}
