import { EVENTS, isWidgetMessage } from './events';
import {
  createInlineEmbed,
  createModalOverlay,
  markOverlayReady,
  teardownOverlay,
  type OverlayHandles,
} from './overlay';
import type {
  CheckoutState,
  CloseReason,
  JovePayCheckoutOptions,
  ResolvedCheckoutConfig,
} from './types';
import { allowedOrigins, buildEmbedUrl, resolveConfig } from './url';

/**
 * Parent-page SDK that embeds JOVEpay portal widgets in an iframe.
 *
 * Modernized from the Konnadex webview pattern: instance-scoped state,
 * origin-checked postMessage, query-param driven embeds (no init payload),
 * and both modal + inline display modes.
 */
export class JovePayCheckout {
  /** Event name constants (same values the portal posts to the parent). */
  static readonly EVENTS = EVENTS;

  private readonly config: ResolvedCheckoutConfig;
  private readonly embedUrl: string;
  private readonly origins: Set<string>;
  private state: CheckoutState = 'idle';
  private handles: OverlayHandles | null = null;
  private messageHandler: ((event: MessageEvent) => void) | null = null;
  private lastClosePayload: Record<string, unknown> | undefined;
  private readyAnnounced = false;

  constructor(options: JovePayCheckoutOptions) {
    if (typeof window === 'undefined' || typeof document === 'undefined') {
      throw new Error('JovePayCheckout can only run in a browser environment.');
    }
    this.config = resolveConfig(options);
    this.embedUrl = buildEmbedUrl(this.config);
    this.origins = allowedOrigins(this.config.baseUrl);
  }

  /** Factory helper for vanilla script usage (`JovePayCheckout.create({…})`). */
  static create(options: JovePayCheckoutOptions): JovePayCheckout {
    return new JovePayCheckout(options);
  }

  /** Current lifecycle state. */
  getStatus(): CheckoutState {
    return this.state;
  }

  /** Fully resolved embed URL that will be loaded in the iframe. */
  getEmbedUrl(): string {
    return this.embedUrl;
  }

  /**
   * Open as a fullscreen modal overlay.
   * Prefer `mount(el)` when `display: 'inline'` was configured.
   */
  open(): this {
    if (this.config.display === 'inline') {
      throw new Error(
        'JovePayCheckout: call `mount(container)` when display is `"inline"`.',
      );
    }
    if (this.state === 'open' || this.state === 'opening') {
      return this;
    }

    this.state = 'opening';
    this.readyAnnounced = false;
    this.handles = createModalOverlay({
      src: this.embedUrl,
      title: this.config.mode === 'payment' ? 'JOVEpay Checkout' : 'JOVEpay Donate',
      closeOnBackdrop: this.config.closeOnBackdrop,
      closeOnEscape: this.config.closeOnEscape,
      onRequestClose: () => this.close('user'),
    });

    this.bindMessages();
    this.watchIframeLoad();
    this.state = 'open';
    return this;
  }

  /**
   * Mount the widget into a host element (inline embed).
   * Works regardless of `display`, but skips the modal chrome.
   */
  mount(container: HTMLElement | string): this {
    const host =
      typeof container === 'string'
        ? document.querySelector<HTMLElement>(container)
        : container;

    if (!host) {
      throw new Error('JovePayCheckout: mount container not found.');
    }

    if (this.state === 'open' || this.state === 'opening') {
      this.close('superseded');
    }

    this.state = 'opening';
    this.readyAnnounced = false;
    this.handles = createInlineEmbed({
      container: host,
      src: this.embedUrl,
      title: this.config.mode === 'payment' ? 'JOVEpay Checkout' : 'JOVEpay Donate',
    });

    this.bindMessages();
    this.watchIframeLoad();
    this.state = 'open';
    return this;
  }

  /** Close the widget and tear down DOM + listeners. */
  close(reason: CloseReason = 'api'): this {
    if (this.state === 'idle' || this.state === 'closed' || this.state === 'closing') {
      return this;
    }

    this.state = 'closing';
    this.unbindMessages();
    teardownOverlay(this.handles);
    this.handles = null;
    this.readyAnnounced = false;
    this.state = 'closed';

    this.config.onClose?.(reason, this.lastClosePayload);
    return this;
  }

  /** Alias for `close('destroy')` — permanently dispose this instance. */
  destroy(): void {
    this.close('destroy');
  }

  private watchIframeLoad(): void {
    const iframe = this.handles?.iframe;
    if (!iframe) {
      return;
    }
    iframe.addEventListener(
      'load',
      () => {
        // Fallback ready: portal may also emit WIDGET_READY.
        // Prefer the explicit event when present; use load as a soft ready.
        if (this.handles?.loader && !this.handles.loader.getAttribute('data-hidden')) {
          // Keep loader until WIDGET_READY, but reveal after a short grace if silent.
          window.setTimeout(() => {
            if (
              this.handles?.loader &&
              !this.handles.loader.getAttribute('data-hidden')
            ) {
              this.handleReady();
            }
          }, 400);
        }
      },
      { once: true },
    );
  }

  private bindMessages(): void {
    this.unbindMessages();
    this.messageHandler = (event: MessageEvent) => {
      if (!this.origins.has(event.origin)) {
        return;
      }
      if (!isWidgetMessage(event.data)) {
        return;
      }

      const { event: widgetEvent } = event.data;
      this.config.onEvent?.(widgetEvent);

      switch (widgetEvent.name) {
        case EVENTS.WIDGET_READY:
          this.handleReady();
          break;
        case EVENTS.WIDGET_CLOSE:
          this.lastClosePayload = widgetEvent.payload;
          this.close('user');
          break;
        case EVENTS.PAYMENT_INIT:
          this.config.onInit?.(widgetEvent.payload);
          break;
        case EVENTS.PAYMENT_SUCCESS:
        case EVENTS.PAYMENT_FINISHED:
        case EVENTS.PAYMENT_CONFIRMED:
          this.lastClosePayload = widgetEvent.payload;
          this.config.onSuccess?.(widgetEvent.payload);
          if (this.config.autoCloseOnSuccess && this.config.display === 'modal') {
            this.close('success');
          }
          break;
        case EVENTS.PAYMENT_FAILED:
        case EVENTS.PAYMENT_EXPIRED:
          this.lastClosePayload = widgetEvent.payload;
          this.config.onError?.(widgetEvent.payload);
          if (this.config.autoCloseOnError && this.config.display === 'modal') {
            this.close('error');
          }
          break;
        default:
          break;
      }
    };
    window.addEventListener('message', this.messageHandler);
  }

  private unbindMessages(): void {
    if (this.messageHandler) {
      window.removeEventListener('message', this.messageHandler);
      this.messageHandler = null;
    }
  }

  private handleReady(): void {
    if (this.readyAnnounced) {
      return;
    }
    this.readyAnnounced = true;
    if (this.handles) {
      markOverlayReady(this.handles);
    }
    this.config.onReady?.();
  }
}

/**
 * Convenience factory — same as `new JovePayCheckout(options)`.
 */
export function createCheckout(
  options: JovePayCheckoutOptions,
): JovePayCheckout {
  return new JovePayCheckout(options);
}
