import {
  DOM_IDS,
  IFRAME_ALLOW,
  IFRAME_SANDBOX,
} from './constants';
import { LOADER_STYLES } from './styles';

export type OverlayHandles = {
  overlay: HTMLElement | null;
  iframe: HTMLIFrameElement;
  loader: HTMLElement | null;
  host: HTMLElement | null;
  previousOverflow: string;
  onBackdropClick?: (event: MouseEvent) => void;
  onKeyDown?: (event: KeyboardEvent) => void;
};

function ensureStyles(): void {
  if (document.getElementById(DOM_IDS.style)) {
    return;
  }
  const style = document.createElement('style');
  style.id = DOM_IDS.style;
  style.textContent = LOADER_STYLES;
  document.head.appendChild(style);
}

function createLoader(): HTMLElement {
  const loader = document.createElement('div');
  loader.id = DOM_IDS.loader;
  loader.setAttribute('role', 'status');
  loader.setAttribute('aria-live', 'polite');
  loader.setAttribute('aria-label', 'Loading JOVEpay');
  return loader;
}

function createIframe(src: string, title: string): HTMLIFrameElement {
  const iframe = document.createElement('iframe');
  iframe.id = DOM_IDS.iframe;
  iframe.src = src;
  iframe.title = title;
  iframe.setAttribute('sandbox', IFRAME_SANDBOX);
  iframe.setAttribute('allow', IFRAME_ALLOW);
  iframe.setAttribute('allowfullscreen', 'true');
  iframe.setAttribute('referrerpolicy', 'strict-origin-when-cross-origin');
  return iframe;
}

export function createModalOverlay(options: {
  src: string;
  title: string;
  closeOnBackdrop: boolean;
  closeOnEscape: boolean;
  onRequestClose: () => void;
}): OverlayHandles {
  ensureStyles();
  teardownOverlay();

  const overlay = document.createElement('div');
  overlay.id = DOM_IDS.overlay;
  overlay.setAttribute('role', 'dialog');
  overlay.setAttribute('aria-modal', 'true');
  overlay.setAttribute('aria-label', options.title);

  const loader = createLoader();
  const iframe = createIframe(options.src, options.title);

  overlay.appendChild(loader);
  overlay.appendChild(iframe);
  document.body.prepend(overlay);

  const previousOverflow = document.body.style.overflow;
  document.body.style.overflow = 'hidden';

  const handles: OverlayHandles = {
    overlay,
    iframe,
    loader,
    host: null,
    previousOverflow,
  };

  if (options.closeOnBackdrop) {
    handles.onBackdropClick = (event: MouseEvent) => {
      if (event.target === overlay) {
        options.onRequestClose();
      }
    };
    overlay.addEventListener('click', handles.onBackdropClick);
  }

  if (options.closeOnEscape) {
    handles.onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.preventDefault();
        options.onRequestClose();
      }
    };
    window.addEventListener('keydown', handles.onKeyDown);
  }

  // Trigger enter transition on next frame
  requestAnimationFrame(() => {
    overlay.setAttribute('data-open', 'true');
  });

  return handles;
}

export function createInlineEmbed(options: {
  container: HTMLElement;
  src: string;
  title: string;
}): OverlayHandles {
  ensureStyles();
  teardownOverlay();

  options.container.classList.add('jovepay-webpay-inline-host');
  const loader = createLoader();
  const iframe = createIframe(options.src, options.title);
  iframe.setAttribute('data-inline', 'true');

  options.container.replaceChildren(loader, iframe);

  return {
    overlay: null,
    iframe,
    loader,
    host: options.container,
    previousOverflow: '',
  };
}

export function markOverlayReady(handles: OverlayHandles): void {
  handles.loader?.setAttribute('data-hidden', 'true');
  handles.overlay?.setAttribute('data-ready', 'true');
  if (handles.host) {
    handles.loader?.setAttribute('data-hidden', 'true');
  }
  handles.iframe.focus({ preventScroll: true });
}

export function teardownOverlay(handles?: OverlayHandles | null): void {
  if (handles?.onBackdropClick && handles.overlay) {
    handles.overlay.removeEventListener('click', handles.onBackdropClick);
  }
  if (handles?.onKeyDown) {
    window.removeEventListener('keydown', handles.onKeyDown);
  }
  if (handles && handles.previousOverflow !== undefined) {
    document.body.style.overflow = handles.previousOverflow;
  }

  const overlay = document.getElementById(DOM_IDS.overlay);
  if (overlay?.parentNode) {
    overlay.parentNode.removeChild(overlay);
  }

  const orphanIframe = document.getElementById(DOM_IDS.iframe);
  if (orphanIframe?.parentNode && orphanIframe.id === DOM_IDS.iframe) {
    const parent = orphanIframe.parentElement;
    orphanIframe.parentNode.removeChild(orphanIframe);
    parent?.querySelector(`#${DOM_IDS.loader}`)?.remove();
  }
}
