import {
  DEVELOPMENT_ORIGIN,
  EMBED_PATHS,
  PAY_BASE_PATH,
  PRODUCTION_ORIGIN,
} from './constants';
import type {
  CheckoutPaymentData,
  CmsPaymentOptions,
  JovePayCheckoutOptions,
  JovePayEnvironment,
  ResolvedCheckoutConfig,
} from './types';

function trimTrailingSlash(url: string): string {
  return url.replace(/\/+$/, '');
}

export function resolveOrigin(
  env: JovePayEnvironment = 'production',
  baseUrl?: string,
): string {
  if (baseUrl) {
    return trimTrailingSlash(baseUrl);
  }
  return env === 'development' ? DEVELOPMENT_ORIGIN : PRODUCTION_ORIGIN;
}

function stringifyQuery(
  entries: Record<string, string | number | boolean | undefined | null>,
): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [key, value] of Object.entries(entries)) {
    if (value === undefined || value === null || value === '') {
      continue;
    }
    out[key] = String(value);
  }
  return out;
}

function assertNoIpnCallbackUrl(options: object): void {
  if (
    'ipnCallbackUrl' in options &&
    (options as { ipnCallbackUrl?: unknown }).ipnCallbackUrl != null
  ) {
    throw new Error(
      'JovePayCheckout: `ipnCallbackUrl` is not allowed. Configure IPN on the merchant server / dashboard.',
    );
  }
}

function isCmsPayment(
  options: JovePayCheckoutOptions,
): options is CmsPaymentOptions {
  return (
    options.mode === 'payment' &&
    typeof (options as CmsPaymentOptions).apiKey === 'string' &&
    (options as CmsPaymentOptions).orderId != null &&
    (options as CmsPaymentOptions).priceAmount != null &&
    typeof (options as CmsPaymentOptions).priceCurrency === 'string'
  );
}

function pickPaymentData(options: CmsPaymentOptions): CheckoutPaymentData {
  const data: CheckoutPaymentData = {
    apiKey: options.apiKey,
    orderId: options.orderId,
    priceAmount: options.priceAmount,
    priceCurrency: options.priceCurrency,
  };

  if (options.successUrl) data.successUrl = options.successUrl;
  if (options.cancelUrl) data.cancelUrl = options.cancelUrl;
  if (options.customerName) data.customerName = options.customerName;
  if (options.customerEmail) data.customerEmail = options.customerEmail;
  if (options.products !== undefined) data.products = options.products;
  if (options.shipping !== undefined) data.shipping = options.shipping;
  if (options.tax !== undefined) data.tax = options.tax;
  if (options.subtotal !== undefined) data.subtotal = options.subtotal;
  data.dataSource = options.dataSource ?? 'web';

  const isTestnet = options.isTestnet ?? false;
  if (isTestnet) data.isTestnet = true;

  return data;
}

/**
 * Base64-encode CMS checkout JSON (UTF-8 safe).
 * Pass the result to `URLSearchParams` / `URL` so it is percent-encoded once —
 * matching CMS plugins: `urlencode(base64(json))`.
 */
export function encodePaymentParams(data: CheckoutPaymentData): string {
  const json = JSON.stringify(data);
  const bytes = new TextEncoder().encode(json);
  let binary = '';
  for (const byte of bytes) {
    binary += String.fromCharCode(byte);
  }
  return btoa(binary);
}

export function resolveConfig(
  options: JovePayCheckoutOptions,
): ResolvedCheckoutConfig {
  assertNoIpnCallbackUrl(options);

  if (options.mode === 'payment') {
    const hasInvoice =
      typeof options.invoiceId === 'string' && options.invoiceId.length > 0;
    const cms = isCmsPayment(options);

    if (hasInvoice && cms) {
      throw new Error(
        'JovePayCheckout: pass either `invoiceId` or CMS payment fields (`apiKey`, `orderId`, …), not both.',
      );
    }
    if (!hasInvoice && !cms) {
      throw new Error(
        'JovePayCheckout: payment mode requires `invoiceId` or CMS fields (`apiKey`, `orderId`, `priceAmount`, `priceCurrency`).',
      );
    }
  }

  if (options.mode === 'donation' && !options.apiKey) {
    throw new Error('JovePayCheckout: `apiKey` is required for donation mode.');
  }

  const display = options.display ?? 'modal';
  const baseUrl = resolveOrigin(options.env ?? 'production', options.baseUrl);
  const paymentData =
    options.mode === 'payment' && isCmsPayment(options)
      ? pickPaymentData(options)
      : undefined;

  return {
    mode: options.mode,
    invoiceId:
      options.mode === 'payment' && options.invoiceId
        ? options.invoiceId
        : undefined,
    apiKey: options.mode === 'donation' ? options.apiKey : paymentData?.apiKey,
    paymentData,
    baseUrl,
    theme: options.theme ?? 'light',
    locale: options.locale ?? 'en',
    isTestnet: options.isTestnet ?? paymentData?.isTestnet ?? false,
    paymentId: options.paymentId,
    display,
    autoCloseOnSuccess: options.autoCloseOnSuccess ?? display === 'modal',
    autoCloseOnError: options.autoCloseOnError ?? false,
    closeOnBackdrop: options.closeOnBackdrop ?? true,
    closeOnEscape: options.closeOnEscape ?? true,
    query: stringifyQuery(options.query ?? {}),
    onReady: options.onReady,
    onInit: options.onInit,
    onSuccess: options.onSuccess,
    onError: options.onError,
    onClose: options.onClose,
    onEvent: options.onEvent,
  };
}

/**
 * Builds the portal embed URL for payment or donation widgets.
 *
 * Invoice: `/pay/embeds/payment-widget?iid=…`
 * CMS:     `/pay/embeds/payment-widget?params=…` (base64 JSON, no ipnCallbackUrl)
 * Donation:`/pay/embeds/donation-widget?apiKey=…`
 */
export function buildEmbedUrl(config: ResolvedCheckoutConfig): string {
  const path =
    config.mode === 'payment' ? EMBED_PATHS.payment : EMBED_PATHS.donation;
  const url = new URL(`${config.baseUrl}${PAY_BASE_PATH}${path}`);

  if (config.mode === 'payment') {
    if (config.paymentData) {
      url.searchParams.set('params', encodePaymentParams(config.paymentData));
    } else if (config.invoiceId) {
      url.searchParams.set('iid', config.invoiceId);
    }
  }

  if (config.mode === 'donation' && config.apiKey) {
    url.searchParams.set('apiKey', config.apiKey);
  }
  if (config.paymentId) {
    url.searchParams.set('pid', config.paymentId);
  }
  if (config.isTestnet) {
    url.searchParams.set('isTestnet', 'true');
  }
  url.searchParams.set('theme', config.theme);
  url.searchParams.set('locale', config.locale);

  for (const [key, value] of Object.entries(config.query)) {
    url.searchParams.set(key, value);
  }

  return url.href;
}

/** Allowed `event.origin` values for postMessage verification. */
export function allowedOrigins(baseUrl: string): Set<string> {
  const origins = new Set<string>([baseUrl]);
  try {
    origins.add(new URL(baseUrl).origin);
  } catch {
    // ignore invalid baseUrl — caller already validated via URL construction
  }
  return origins;
}
